registerRefData('nsw-cond-n-322',{"id":322,"pan":null,"ref":"DA 16-2024-656-1","address":"5 Jeffries Circuit Williamtown 2318,9 Jeffries Circuit Williamtown 2318,11 Jeffries Circuit Williamtown 2318","description":"New Car Park and Site Access","outcome":"approved","outcome_raw":"Approved","outcome_source":"planning_panels","determined":"2025-06-27","notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPSHCC-339!20250627T051841.907 GMT","sha256":"85ed0124e863db026d04cf5f896a6c12f3ba3a0e954c44c63e943188dd227c67","pages":25,"layout":"numbered","n":91,"fetched_at":"2026-08-16T23:19:06+00:00","file":"n/322.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/new-car-park-and-site-access","lga":"PORT STEPHENS","conditions":[{"label":"1","code":null,"number":"1","title":"","text":"PANEL REF - LGA - DA NO. PPSHCC-339 - Port Stephens- DA 16 -2024 - 656 - 1","stage":"general","stage_basis":"heading","page":3},{"label":"2","code":null,"number":"2","title":"","text":"PROPOSED DEVELOPMENT Demolition of existing building, construction of site access and a car park with\nassociated security building, gates and fencing and landscaping","stage":"general","stage_basis":"heading","page":3},{"label":"3","code":null,"number":"3","title":"STREET ADDRESS 5 Jeffries Circuit, Williamtown 2318","text":"","stage":"general","stage_basis":"heading","page":3},{"label":"4","code":null,"number":"4","title":"APPLICANT/OWNER BAE Systems Australia Limited /","text":"Greater Newcastle Aerotropolis Pty Ltd / Commonwealth of Australia","stage":"general","stage_basis":"heading","page":3},{"label":"5","code":null,"number":"5","title":"TYPE OF REGIONAL","text":"DEVELOPMENT Council related development over $5 million","stage":"general","stage_basis":"heading","page":3},{"label":"6","code":null,"number":"6","title":"RELEVANT MANDATORY","text":"CONSIDERATIONS\n• Environmental planning instruments:\no State Environmental Planning Policy (Biodiversity and Conservation)\n2021\no State Environmental Planning Policy (Industry and Employment) 2021\no State Environmental Planning Policy (Planning Systems) 2021\no State Environmental Planning Policy (Precincts Regional) 2021\no State Environmental Planning Policy (Resilience and Hazards) 2021\no State Environmental Planning Policy (Transport and Infrastructure)\n2021\no State Environmental Planning Policy (Sustainable Buildings) 2022\no Port Stephens Local Environmental Plan 2013\n• Draft environmental planning instruments: Draft Remediation of Land State\nEnvironmental Planning Policy\n• Development control plans:\no Port Stephens Development Control Plan 2014\n• Planning agreements: Nil\n• Relevant provisions of the Environmental Planning and Assessment\nRegulation 2021: Nil\n• Coastal zone management plan: Nil\n• The likely impacts of the development, including environmental impacts on\nthe natural and built environment and social and economic impacts in the\nlocality\n• The suitability of the site for the development\n• Any submissions made in accordance with the Environmental Planning and\nAssessment Act 1979 or regulations\n• The public interest, including the principles of ecologically sustainable\ndevelopment","stage":"general","stage_basis":"heading","page":3},{"label":"7","code":null,"number":"7","title":"MATERIAL CONSIDERED BY","text":"THE PANEL\n• Council Assessment Report: 10 June 2025\n• Council Addendum Assessment report: 20 June 2025\n• Written submissions during public exhibition: 0\n• Total number of unique submissions received by way of objection: 0","stage":"general","stage_basis":"heading","page":3},{"label":"8","code":null,"number":"8","title":"MEETINGS, BRIEFINGS AND","text":"SITE INSPECTIONS BY THE\nPANEL\n• Initial Briefing: 4 March 2025\no Panel members: Alison McCabe (Chair), Roberta Ryan, Tony McNamara\no Council assessment staff: Isaac Lancaster, Mat Egan\n• Site inspection:\nRoberta Ryan: 12 April 2025\n• Final briefing to discuss council’s recommendation: 17 June 2025\no Panel members: Tony McNamara (Alternate Chair), Roberta Ryan,\nSusan Budd\no Council assessment staff: Isaac Lancaster, Matt Egan\no Applicant representatives: Kevin Morris, James Phair, David Mattiussi,\nNathan Muggleton, Rebecca Johnston","stage":"general","stage_basis":"heading","page":3},{"label":"9","code":null,"number":"9","title":"COUNCIL RECOMMENDATION","text":"Approval","stage":"general","stage_basis":"heading","page":3},{"label":"10","code":null,"number":"10","title":"DRAFT CONDITIONS Attached to the Council Assessment Report and Addendum report","text":"SCHEDULE 2","stage":"general","stage_basis":"heading","page":3},{"label":"1","code":null,"number":"1","title":"Approved plans and supporting documentation","text":"Development must be carried out in accordance with the following approved plans and documents,\nexcept where the conditions of this consent expressly require otherwise.\nApproved plans\nPlan number Revision\nnumber\nPlan title Drawn by Date of plan\nDA002 E Site Analysis Plan Design Inc 25/11/2024\nDA004 I Existing & Demolition\nPlan\nDesign Inc 22/04/2025\nDA006 I Overall Site Plan Design Inc 22/04/2025\nDA010 P Proposed Ground\nFloor Plan 01\nDesign Inc 22/04/2025\nDA011 J Proposed Ground\nFloor Plan 02\nDesign Inc 25/11/2024\nDA012 H Boundary Elevations Design Inc 22/04/2025\nDA100 G Proposed\nGuardhouse & Office\nPlan\nDesign Inc 25/11/2024\nDA101 E Proposed Buildings -\nRoof Plan\nDesign Inc 25/11/2024\nDA200 E Proposed Parking\nCanopies - Ground\nFloor Plan\nDesign Inc 25/11/2024\nDA201 E Proposed Parking\nCanopies - Roof Plan\nDesign Inc 25/11/2024\nDA300 E Proposed Building -\nElevations\nDesign Inc 25/11/2024\nDA301 D Proposed Buildings -\nElevations\nDesign Inc 25/11/2024\nDA350 E Proposed\nGuardhouse & Office\n- Sections\nDesign Inc 25/11/2024\nDA351 E Proposed Parking\nCanopies - Section\nDesign Inc 25/11/2024\nLA002 F Landscape Site Plan","stage":"general","stage_basis":"heading","page":4},{"label":"1","code":null,"number":"1","title":"Design Inc 22/04/2025","text":"LA003 D Landscape Site Plan","stage":"general","stage_basis":"heading","page":5},{"label":"2","code":null,"number":"2","title":"Design Inc 25/11/2024","text":"LA004 F Landscape Plan -\nStaff Rest Area\nDesign Inc 22/04/2025\nLA005 D Landscape - Sections Design Inc 25/11/2024\nLA006 D Landscape - Details Design Inc 25/11/2024\nLA007 C Landscape - Planting\nSchedule\nDesign Inc 25/11/2024\nPEW-C02.01 2 Erosion and\nSediment Control\nPlan\nNorthrop 5/08/2024\nPEW-C02.11 2 Erosion and\nSediment Control\nDetails\nNorthrop 5/08/2024\nPEW-C04.01 6 Civil Works Plan -\nSheet 1\nNorthrop 11/11/2024\nPEW-C04.02 5 Civil Works Plan -\nSheet 2\nNorthrop 11/11/2024\nPEW-C09.01 3 Culvert Section Northrop 30/08/2024\nLM01 2 Light Modelling\nCalculations Area\nNorthrop 2/08/2024\nPEW-L01.02 1 Concept Lighting\nLayout Sheet 2\nNorthrop 4/09/2024\nApproved Documents\nDocument title Version\nNo.\nPrepared by Dated\nStormwater Management & Servicing Plan\nReference: NL223031-00-CV-RP01\nI Northrop 11/11/2024\nAcoustic Assessment\nReference: 20241271.1\n2 Acoustic Logic 17/12/2024\nOperational Waste Management Plan B Elephants Foot\nConsulting\n3/09/2024\nConstruction & Demolition Waste\nManagement Plan\nB Elephants Foot\nConsulting\n3/09/2024\nHazardous Materials Assessment 1 EDP 15/08/2024\nReference: S-\n06314.HMA.001_20231116_Building 5\nPreliminary Site Investigation\nReference: S20283_014_RPT_Rev1\n0 Senversa 16/07/2024\nAccess Report\nReference: 117161\n2 Jensen Hughes 5/09/2024\nBushfire Threat Assessment\nReference: 4313\n2 AEP 3/09/2024\nArboricultural Impact Assessment\nReference: Jeffries Circuit, Williamtown\nNSW","stage":"general","stage_basis":"heading","page":5},{"label":"3","code":null,"number":"3","title":"Agility 9/10/2024","text":"Crime Prevention Through Environmental\nDesign Assessment\nReference: 2230841\n2 Ethos Urban 5/09/2024\nIn the event of any inconsistency with the approved plans and a condition of this consent, the\ncondition prevails.\n2. Department of Defence, Reference: ID-EP-DLP&R/OUT/2025/ BS63030805, dated 8 January\n2025.\n3. Ausgrid, Reference:1900133305, dated 20 December 2024.\n3 Building Code of Australia\nAll building work must be carried out in accordance with the BCA. In this clause, a reference to the\nBCA is a reference to that Code as in force on the date the application for the relevant Construction\nCertificate is made.","stage":"general","stage_basis":"heading","page":6},{"label":"4","code":null,"number":"4","title":"Sign on Building","text":"Except in the case of work only carried out to the interior of a building or Crown building work, a sign\nmust be erected in a prominent position on the site showing the name, address and telephone\nnumber of the Principal Certifying Authority for the work, the name of any principal contractor and\ntheir after-hours contact number, and must contain a statement that unauthorised entry to the site\nis prohibited.\nThe sign must be maintained while the work is being carried out and is to be removed when the\nwork is completed.","stage":"general","stage_basis":"heading","page":6},{"label":"5","code":null,"number":"5","title":"Building Materials","text":"Building materials used for construction are to be non-reflective. If it is later found that glare\nendangers the safety of aircraft operations, the Department of Defence may require material and\ndesign modifications at full cost to the proponent.","stage":"general","stage_basis":"heading","page":7},{"label":"6","code":null,"number":"6","title":"Protection of existing vegetation and natural landscape features","text":"No vegetation or natural landscape features other than that authorized for removal, pruning by this\nConsent must be disturbed, damaged, or removed. No additional works or access/parking routes\ntransecting the protected vegetation must be undertaken without Council Approval.","stage":"general","stage_basis":"heading","page":7},{"label":"7","code":null,"number":"7","title":"Tree Removal/Pruning","text":"Trees 5 and 6 as identified on Page 25 of the ‘Arboricultural Impact Assessment’, prepared by Agility\nProfessional Tree Service, dated 9/10/2024 are approved for removal.\nAll other trees identified within the Arboricultural Impact Assessment must be retained. All\nrecommendations made within the Arboricultural Impact Assessment are to be complied with during\nall stages of development.\nApproval to remove existing vegetation for removal is not to occur until the issue of the Construction\nCertificate.","stage":"general","stage_basis":"heading","page":7},{"label":"8","code":null,"number":"8","title":"Staging of Development","text":"The development is to be completed in two (2) stages, with the portion of works occurring on Lot 43\nDP 1045602 to occur as a separate construction stage (stage 2).\nBuilding Work","stage":"general","stage_basis":"heading","page":7},{"label":"9","code":null,"number":"9","title":"Erosion and sediment controls plan","text":"Before the issue of a Construction Certificate, an erosion and sediment control plan must be\nprepared by a suitably qualified person in accordance with the following documents and provided to\nthe certifier:\n1. Council’s relevant development control plan,\n2. the guidelines set out in 'Managing Urban Stormwater: Soils and Construction’ prepared by\nLandcom (the Blue Book) (as amended from time to time), and\n3. The ‘Do it Right On-Site, Soil and Water Management for the Construction Industry'\n(Southern Sydney Regional Organisation of Councils and the Natural Heritage Trust) (as\namended from time to time).","stage":"before_cc","stage_basis":"heading","page":7},{"label":"10","code":null,"number":"10","title":"Waste Management Plan requirements","text":"Before the issue of a Construction Certificate, a waste management plan for the development must\nbe prepared and provided to the certifier. The plan must be prepared:\na. in accordance with\ni. the Environment Protection Authority’s Waste Classification Guidelines as in force\nfrom time to time; and\nii. a development control plan that provides for waste management that applies to the\nland on which the work or the clearing of vegetation is carried out; and\nb. include the following information-\ni. the contact details of the person removing waste;\nii. an estimate of the type and quantity of waste;\niii. whether waste is expected to be reused, recycled or sent to landfill;\niv. the address of the disposal location for waste.\nA copy of the waste management plan must be kept on-site at all times while work approved under\nthe development consent is being carried out.","stage":"before_cc","stage_basis":"heading","page":8},{"label":"11","code":null,"number":"11","title":"Section 7.12 development contributions","text":"A monetary contribution is to be paid to Council, pursuant to Section 7.12 of the Environmental\nPlanning & Assessment Act 1979 and the Port Stephens Local Infrastructure Contribution Plan 2020.\nThe total amount payable will be adjusted at the time payment is made, in accordance with the\nprovisions of that Plan.\nSection 7.12 contributions will be calculated with reference to the capital investment value (CIV) of\nthe development, determined in accordance with Clause 25J of the Environmental Planning and\nAssessment Regulation 2021, and the levies specified in the Port Stephens Local Infrastructure\nContributions Plan 2020as outlined below:\nCapital Investment Value Levy Rate (% of CIV)\nUp to and including $100,000 Nil\nMore than $100,000 and up to and including\n$200,000\n0.5%\nMore than $200,000 1%\nThe payment of the Fixed Local Infrastructure Contribution levy, is to be accompanied by a Cost\nSummary Report Form setting out an estimate of the CIV in accordance with Schedule 1 of the Port\nStephens Local Infrastructure Contributions Plan. A copy of the\nPlan and Cost Summary Report Forms\nare available Council’s website at https://www.portstephens.nsw.gov.au/, alternatively contact\nCouncil on 02 9228 055.\nWhere the estimated cost of carrying out on the whole of the development is more than $1,000,000,\nthe Cost Summary Report Form must be completed by a Quantity Surveyor who is a Registered\nAssociate member or above, of the Australia Institute of Quantity Surveyors.\nThis condition cannot be taken to be satisfied until a payment has been made in accordance with the\nCIV stated on a cost summary report submitted to Council in accordance with this condition.\nPayment of the above amount must apply to Development Applications as follows:\na) Building work only - prior to issue of the Construction Certificate.","stage":"before_cc","stage_basis":"heading","page":8},{"label":"12","code":null,"number":"12","title":"Long Service Levy","text":"Before the issue of a Construction Certificate, the long service levy must be paid to the Long Service\nCorporation under the Building and Construction industry Long Service Payments Act 1986, section\n34, and evidence of the payment is to be provided to the principal certifier","stage":"before_cc","stage_basis":"heading","page":9},{"label":"13","code":null,"number":"13","title":"Roads Act Approval","text":"Prior to issue of a Construction Certificate, for construction/reconstruction of Council infrastructure,\nincluding vehicular crossings, footpath, kerb and gutter, stormwater drainage, an application must be\nmade for a Roadworks Permit under Section 138 of the Roads Act 1993.","stage":"before_cc","stage_basis":"heading","page":9},{"label":"14","code":null,"number":"14","title":"Stormwater/Drainage Plans","text":"Detailed stormwater drainage plans must be prepared by a qualified Engineer in accordance with the\napproved plans, Council’s Infrastructure Specifications and the current Australian Rainfall and Runoff\nguidelines using the Hydrologic Soil Mapping data for Port Stephens (available from Council).\nDetails demonstrating compliance must be provided to the Certifying Authority prior to issue of a\nConstruction Certificate.\nNote: Under the Roads Act 1993, only the Roads Authority can approve commencement of works\nwithin an existing road reserve.","stage":"before_cc","stage_basis":"heading","page":9},{"label":"15","code":null,"number":"15","title":"Civil engineering plans","text":"Civil engineering plans prepared by a qualified Engineer, indicating drainage, roads, access ways,\nearthworks, pavement design, street lighting, details of line-marking, traffic management, water\nquality and quantity facilities including stormwater detention and disposal, must be prepared in\naccordance with the approved plans and Council’s Infrastructure Specifications.\nDetails demonstrating compliance must be provided to the Certifying Authority prior to issue of a\nConstruction Certificate.\nNote. Under the Roads Act 1993, only the Roads Authority can approve commencement of works\nwithin an existing road reserve.","stage":"before_cc","stage_basis":"heading","page":9},{"label":"16","code":null,"number":"16","title":"Construction Site Management Plan","text":"Before the issue of a Construction Certificate, a construction site management plan must be\nprepared, and provided to the principal certifier. The plan must include the following matters:\na. The location and materials for protective fencing and hoardings on the perimeter of the site;\nb. Provisions for public safety;\nc. Pedestrian and vehicular site access points and construction activity zones;\nd. Details of construction traffic management including:\ni. Proposed truck movements to and from the site;\nii. Estimated frequency of truck movements; and\niii. Measures to ensure pedestrian safety near the site;\ne. Details of bulk earthworks to be carried out;\nf. The location of site storage areas and sheds;\ng. The equipment used to carry out works;\nh. The location of a garbage container with a tight-fitting lid;\ni. Dust, noise and vibration control measures;\nj. The location of temporary toilets;\nk. The protective measures for the preservation of trees on-site and in adjoining public areas\nincluding measures in accordance with:\ni. AS 4970 - Protection of trees on development sites;\nii. An applicable Development Control Plan;\niii. An arborist’s report approved as part of this consent\nA copy of the construction site management plan must be kept on site at all times while work is\nbeing carried out.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"17","code":null,"number":"17","title":"PFAS Contamination Management Plan","text":"Before the issue of a Construction Certificate, a PFAS Contamination Management plan is to be\nprepared and include the following actions to manage interaction with PFAS contamination during\nconstruction:\n1. Where the potential for Per- and Poly-Fluoroalkyl Substances (PFAS) contamination exists in\nsoil, groundwater or surface water at the development site, the applicant must identify\nwhether any construction activities could disturb or interact with any PFAS contaminated soil,\ngroundwater or surface water.\n2. If construction activities could disturb or interact with any PFAS contaminated soil,\ngroundwater or surface water, the applicant must:\na. prevent, or limit as far as possible, offsite migration of PFAS contamination;\nb. prevent, or limit as far as possible, contact and exposure to PFAS;\nc. manage potentially PFAS impacted groundwater that may accumulate in any footings or\nexcavations to ensure this does not run-off the site;\nd. manage any PFAS-impacted soils, by controlling erosion and covering stockpiles of PFAS\nimpacted soils to protect from rainfall egress and runoff; and e. ensure that any PFAS\ncontaminated material transported from the site to a site that is lawfully able to receive\nit.\nWhere PFAS contaminated material is to be removed from the site, the applicant must sample the\nsoil for PFAS and classify the soil in accordance with the EPA’s Addendum to the Waste Classification\nGuidelines (2014) - Part 1: classifying waste to identify lawful management and disposal options.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"18","code":null,"number":"18","title":"Hazardous Materials Management Plan","text":"Before the issue of a Construction Certificate, a Hazardous Materials Management Plan (HMMP) is to\nbe prepared to assist with the management of any asbestos containing material and hazardous\nbuilding material. The HMMP must ensure that suitable control measures are implemented to\nprevent site personnel and others from being exposed to airborne asbestos fibres or potentially\ndisturbing other hazardous building material at the site.\nThe HMMP shall be provided to the Certifying Authority and Council for approval, prior to issue of a\nConstruction Certificate.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"19","code":null,"number":"19","title":"Car parking details","text":"Before the issue of the relevant construction certificate, written evidence prepared by a suitably\nqualified engineer must be obtained that demonstrates, to the certifier’s satisfaction, the plans for\nparking facilities comply with the relevant parts of AS 2890.1 Parking Facilities -Off-\nStreet Carparking\nand Chapter B8 of council’s relevant development control plan (in force as at the date of\ndetermination of this consent).","stage":"before_cc","stage_basis":"heading","page":11},{"label":"20","code":null,"number":"20","title":"Retaining walls","text":"All retaining walls within 1m of a boundary and exceeding 600mm in height must be designed and\ncertified by a suitably qualified Structural Engineer.\nDetails demonstrating compliance must be provided to the Certifying Authority prior to issue of a\nConstruction Certificate.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"21","code":null,"number":"21","title":"Equal access to the premises","text":"Before the issue of a construction certificate, plans which demonstrate that adequate access to the\npremises will be provided for persons with disabilities in accordance with the Commonwealth\nDisability (Access to Premises - Buildings) Standards 2010. These plans must be submitted to the\ncertifier.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"22","code":null,"number":"22","title":"Detailed Design in accordance with Acoustic Report","text":"Detailed design of the development is to be in accordance with the recommendations of section 3.2\nof the Acoustic Assessment Report No. 20241271.1, Revision 2, prepared by Acoustic Logic and dated\n17 December 2024. Certification the design accords with the recommended constructions of this\nAcoustic Report by a suitably qualified acoustic engineer, is to be provided to the Certifying\nAuthority.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"23","code":null,"number":"23","title":"Water and Sewer Servicing Requirements","text":"Before the issue of any Construction Certificate, the following water and sewer servicing\nrequirements must be satisfied:\n1. The proponent is required to submit an application for Development Assessment (Section\n50) for the proposed development in accordance with Section 49 of the Hunter Water Act\n1991 (the Act) via the Hunter Water Self Service Portal\n(https://selfservice.hunterwater.com.au/).\n2. A Compliance Certificate will be issued under Section 50 of the Act for each stage of the\nproposed development once Hunter Water’s specific requirements have been satisfied, and\nthis Compliance Certificate must be submitted to the Principal Certifying Authority prior to a\nConstruction Certificate being issued for the development.\n3. The proponent is responsible for ensuring that any development staging is clearly defined in\nthe development consent in order to allow the release of Section 50 Compliance Certificates\nfor each development stage and, if required, the associated staged delivery of water and\nsewer infrastructure.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"24","code":null,"number":"24","title":"Detailed Design in Accordance with CPTED Report","text":"Detailed design of the development is to be in accordance with the recommendations of section 6.0\nof the CPTED Report No. 2230841, prepared by Ethos Urban and dated 5 September 2024.\nFurthermore, all lighting to high-traffic external areas including the carpark, walkways, and entrances\nas referenced in section 6.1.1 of the CPTED Report, must be designed to the minimum Australian\nStandard of AS1158.\nA statement outlining how the detailed design accords with the recommendations referenced within\nthis condition is to be provided to the Certifying Authority prior to issue of any construction certificate.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"25","code":null,"number":"25","title":"Public liability insurance","text":"The owner or contractor must take out a Public Liability Insurance Policy with a minimum cover of\n$20 million in relation to the occupation of, and works within, public property (i.e. kerbs, gutters,\nfootpaths, walkways, reserves, etc.) for the full duration of the proposed works.\nEvidence of this Policy must be provided to Council and the Certifying Authority.","stage":"before_work","stage_basis":"heading","page":12},{"label":"26","code":null,"number":"26","title":"Erosion and sediment controls in place","text":"Before any site work commences, the certifier must be satisfied the erosion and sediment controls in\nthe erosion and sediment control plan are in place. These controls must remain in place until any\nbare earth has been re-stabilized in accordance with 'Managing Urban Stormwater: Soils and\nConstruction’ prepared by Landcom (the Blue Book) (as amended from time to time).","stage":"before_work","stage_basis":"heading","page":13},{"label":"27","code":null,"number":"27","title":"All Weather Access","text":"A 3m wide all-weather vehicle access is to be provided from the kerb and gutter to the building\nunder construction for the delivery of materials and use by trades people.\nNo materials, waste or the like are to be stored on the all-weather access at any time.","stage":"before_work","stage_basis":"heading","page":13},{"label":"28","code":null,"number":"28","title":"Construction Certificate Required","text":"In accordance with the provisions of Section 6.7 of the Environmental Planning & Assessment Act\n1979 (EP&A Act 1979), construction or subdivision works approved by this consent must not\ncommence until the following has been satisfied:\na) A Construction Certificate has been issued by a Consent Authority;\nb) A Principal Certifying Authority (PCA) has been appointed by the person having benefit of the\ndevelopment consent in accordance with Section 6.5 of the EP&A Act 1979; and\nc) The PCA is notified in writing of the name and contractor license number of the\nowner/building intending to carry out the approved work.","stage":"before_work","stage_basis":"heading","page":13},{"label":"29","code":null,"number":"29","title":"Notice Commencement of Work","text":"Notice must be given to Council and the Principal Certifier, if not the Council, of the person’s\nintention to commence the erection of the building or undertake subdivision work at least two days\nprior to subdivision and/or building works commencing in accordance with Sections 6.6 (2) and 6.12\n(2) (c) of the Environmental Planning and Assessment Act 1979 and Section 59 of the Environmental\nPlanning and Assessment (Development Certification and Fire Safety) Regulation 2021. The notice\nmust include:\na) The name and address of the person;\nb) A description of the work to be carried out;\nc) The address of the land on which the work is to be carried out;\nd) The Registered numbers and date of issue of the development consent and construction\ncertificate;\ne) A statement signed by or on behalf of the principal certifier that all conditions of the consent\nthat must be satisfied before work commences have been satisfied; and\nf) The date on which the work is intended to commence.\nThe notice must be lodged on the NSW Planning Portal.","stage":"before_work","stage_basis":"heading","page":13},{"label":"30","code":null,"number":"30","title":"Notice of Principal Certifying Authority Appointment","text":"The Principal Certifier for this development must give notice must be given to the consent authority\nand Council, where the Council is not the consent authority, at least two days prior to subdivision\nand/or building works commencing in accordance with Section 6.6 (2) (a) of the Environmental\nPlanning and Assessment Act 1979 and Section 57 of the Environmental Planning and Assessment\n(Development Certification and Fire Safety) Regulation 2021. The notice must include:\na) A description of the work to be carried out;\nb) The address of the land on which the work is to be carried out;\nc) The Registered number and date of issue of the relevant development consent;\nd) The name and address of the Principal Certifier and the person who appointed the principal\ncertifier;\ne) If the principal certifier is a registered certifier\ni) The certifier’s registration number, and\nii) A statement signed by the registered certifier to the effect that the certifier consents to\nbe appointed as principal certifier, and\niii) A telephone number on which the certifier may be contacted for business purposes.\nThe notice must be lodged on the NSW Planning Portal.","stage":"before_work","stage_basis":"heading","page":14},{"label":"31","code":null,"number":"31","title":"Damage report - Public Infrastructure","text":"Before any site work commences, the applicant is required to notify Council in writing of any existing\ndamage to public infrastructure (including landscaping) within the vicinity of the development, the\nabsence of such notification signifies that no damage exists","stage":"before_work","stage_basis":"heading","page":14},{"label":"32","code":null,"number":"32","title":"Rubbish Generated from the Development","text":"Where not already available, a waste containment facility is to be established on site. The facility is\nto be regularly emptied and maintained for the duration of works.\nNo rubbish must be stockpiled in a manner which facilitates the rubbish to be blown or washed off\nsite. The site must be cleared of all building refuse and spoil immediately upon completion of the\ndevelopment.","stage":"before_work","stage_basis":"heading","page":14},{"label":"33","code":null,"number":"33","title":"Signs on site","text":"A sign must be erected in a prominent position on any site on which building work or demolition\nwork is being carried out:\na) showing the name, address and telephone number of the principal certifier for the work, and\nb) showing the name of the principal contractor (if any) for any building work and a telephone\nnumber on which that person may be contacted outside working hours, and\nc) stating that unauthorised entry to the work site is prohibited.\nAny such sign is to be maintained while the building work or demolition work is being carried out,\nbut must be removed when the work has been completed.\nNote: This does not apply in relation to building work or demolition work that is carried out inside an\nexisting building that does not affect the external walls of the building.","stage":"before_work","stage_basis":"heading","page":15},{"label":"34","code":null,"number":"34","title":"Site is to be secured","text":"The site must be secured and fenced to the satisfaction of the Principal Certifying Authority. All\nhoarding, fencing, or awnings (associated with securing the site during construction is to be removed\nupon the completion of works.","stage":"before_work","stage_basis":"heading","page":15},{"label":"35","code":null,"number":"35","title":"Weed Management","text":"Weed removal and suppression must be undertaken using approved bush regeneration techniques\nunder the supervision of a suitably qualified and approved bush regenerator and in accordance with\nthe requirements for the NSW Biosecurity Act 2015, associated Regulations and NSW Weed Control\nHandbook. The site is to be inspected by a representative of Council’s Invasive Species team one\nweek prior to works commencing.","stage":"before_work","stage_basis":"heading","page":15},{"label":"36","code":null,"number":"36","title":"Demolition Work","text":"All demolition works are to be carried out in accordance with Australian Standard AS 2601 ‘The\ndemolition of Structures’. All waste materials are to be either recycled or disposed of to a licensed\nwaste facility.\nAny asbestos containing material encountered during demolition or works, is to be removed in\naccordance with the requirements of Safe Work NSW and disposed of to an appropriately licenced\nwaste facility.\nEvidence is to be provided to the Certifying Authority demonstrating that asbestos waste has been\ndisposed of in accordance with this condition.","stage":"before_work","stage_basis":"heading","page":15},{"label":"37","code":null,"number":"37","title":"Construction Management Plan implementation","text":"All construction management procedures and systems identified in the approved Construction Site\nManagement Plan must be introduced and maintained during construction of the development.","stage":"during_work","stage_basis":"heading","page":16},{"label":"38","code":null,"number":"38","title":"PFAS Management Plan implementation","text":"All actions and procedures identified in the approved PFAS Management Plan must be introduced\nand maintained during construction of the development.","stage":"during_work","stage_basis":"heading","page":16},{"label":"39","code":null,"number":"39","title":"Hazardous Materials Management Plan","text":"All measures identified in the approved Hazardous Materials Management Plan must be introduced\nand maintained during construction of the development.","stage":"during_work","stage_basis":"heading","page":16},{"label":"40","code":null,"number":"40","title":"Discovery of relics and Aboriginal objects","text":"While site works is being carried out, if a person reasonably suspects a relic or Aboriginal object is\ndiscovered:\na. The work in the area of the discovery must cease immediately;\nb. The following must be notified -\nii. For a relic - the Heritage Council; or\niii. For an Aboriginal object - the person who is the authority for the protection of Aboriginal\nobjects and Aboriginal places in New South Wales under the National Parks and Wildlife\nAct 1974, Section 85.\nSite works may recommence at a time conformed in writing by:\na. For a relic - the Heritage Council; or\nb. For an Aboriginal object - the person who is the authority for the protection of Aboriginal\nobjects and Aboriginal places in New South Wales under the National Parks and Wildlife Act\n1974, section 85","stage":"during_work","stage_basis":"heading","page":16},{"label":"41","code":null,"number":"41","title":"Responsibility for changes to public infrastructure","text":"While site work is being carried out, any costs incurred as a result of the approved removal,\nrelocation or reconstruction of infrastructure (including ramps, footpaths, kerb and gutter, light\npoles, kerb inlet pits, service provider pits, street trees or any other infrastructure in the street\nfootpath area) must be paid as directed by the consent authority.","stage":"during_work","stage_basis":"heading","page":16},{"label":"42","code":null,"number":"42","title":"Waste management","text":"While site work is being carried out:\n1. all waste management must be undertaken in accordance with the waste management plan;\nand\n2. upon disposal of waste, records of the disposal must be compiled and provided to the\ncertifying authority, detailing the following:\na. The contact details of the person(s) who removed the waste;\nb. The waste carrier vehicle registration;\nc. The date and time of waste collection;\nd. A description of the waste (type of waste and estimated quantity) and whether the\nwaste is to be reused, recycled or go to landfill;\ne. The address of the disposal location(s) where the waste was taken;\nf. The corresponding tip docket/receipt from the site(s) to which the waste is\ntransferred, noting date and time of delivery, description (type and quantity) of\nwaste.\nIf waste has been removed from the site under an EPA Resource Recovery Order or Exemption,\nrecords in relation to that Order or Exemption must be maintained and provided to the principal\ncertifier and Council.","stage":"during_work","stage_basis":"heading","page":17},{"label":"43","code":null,"number":"43","title":"Hours of work","text":"Site work must only be carried out between the following times -\n7:00am to 5:00pm on Monday to Saturday\nSite work is not to be carried out outside of these times except where there is an emergency, or\nfor urgent work directed by a police officer or a public authority.","stage":"during_work","stage_basis":"heading","page":17},{"label":"44","code":null,"number":"44","title":"Weed management","text":"All machinery that has operated in affected areas shall be cleaned thoroughly prior to leaving the\nsite. A wash down area shall be established and monitored for priority weeds as defined by the NSW\nBiosecurity Act 2015. Cleaning must include the removal of all mud and plant matter, followed by\nwashing with high pressure water. An area for storage of contaminated spoil that is separate from\nclean material shall be provided during construction.","stage":"during_work","stage_basis":"heading","page":17},{"label":"45","code":null,"number":"45","title":"Unexpected Finds Contingency (General)","text":"Should any suspect materials (identified by unusual staining, odour, discolouration or inclusions such\nas building rubble, asbestos, ash material, etc.) be encountered during any stage of works (including\nearthworks, site preparation or construction works, etc.), such works must cease immediately until a\nqualified environmental specialist has be contacted and conducted a thorough assessment.\nIn the event that contamination is identified as a result of this assessment and if remediation is\nrequired, all works must cease in the vicinity of the contamination and Council must be notified\nimmediately.\nWhere remediation work is required, the applicant will be required to obtain consent for the\nremediation works.","stage":"during_work","stage_basis":"heading","page":17},{"label":"46","code":null,"number":"46","title":"Excavations and Backfilling","text":"All excavations and backfilling associated with this development consent must be executed safely,\nand be properly guarded and protected to prevent them from being dangerous to life or property,\nand in accordance with the design of a suitably qualified Structural Engineer.\nIf an excavation extends below the level of the base of the footings of a building on an adjoining\nallotment, the person causing the excavation must:\na) preserve and protect the building from damage; and\nb) if necessary, underpin and support the building in an approved manner; and\nc) give at least seven days’ notice to the adjoining owners before excavating, or of the intention\nto excavate.\nThe principal contractor, owner builder or any person who needs to excavate and undertake building\nwork, must contact “Dial Before You Dig” prior to works commencing, and allow a reasonable period\nof time for the utilities to provide locations of their underground assets.\nThis condition does not apply if the person having the benefit of the development consent owns the\nadjoining land or the owner of the adjoining land has given consent in writing to that condition not\napplying.","stage":"during_work","stage_basis":"heading","page":18},{"label":"47","code":null,"number":"47","title":"Offensive noise, dust, odour, and vibration","text":"Work must not give rise to offensive noise, odour, or vibration as defined in the Protection of the\nEnvironment Operations Act 1997 when measured at the nearest property boundary.","stage":"during_work","stage_basis":"heading","page":18},{"label":"48","code":null,"number":"48","title":"Toilet Facilities","text":"Temporary toilet(s) must be provided and maintained on site from the time of commencement of\nbuilding work to completion. The number of toilets provided must be one toilet per 20 persons or\npart thereof employed on the site at any one time.\nThe temporary toilet is to be either connected to the sewerage system or an approved septic tank or\notherwise may be a chemical toilet supplied by a licensed contractor.","stage":"during_work","stage_basis":"heading","page":18},{"label":"49","code":null,"number":"49","title":"Compliance with the Building Code of Australia","text":"Building work must be carried out in accordance with the requirements of the Building Code of\nAustralia.","stage":"during_work","stage_basis":"heading","page":18},{"label":"50","code":null,"number":"50","title":"Cut and fill (if applicable)","text":"While building work is being carried out, the principal certifier must be satisfied all soil removed from\nor imported to the site is managed in accordance with the following requirements:\n(a) All excavated material removed from the site must be classified in accordance with the EPA’s\nWaste Classification Guidelines before it is disposed of at an approved waste management\nfacility and the classification and the volume of material removed must be reported to the\nprincipal certifier.\n(b) All fill material imported to the site must be Virgin Excavated Natural Material as defined in\nSchedule 1 of the Protection of the Environment Operations Act 1997 or a material identified\nas being subject to a resource recovery exemption by the NSW EPA.","stage":"during_work","stage_basis":"heading","page":19},{"label":"51","code":null,"number":"51","title":"Placement of fill","text":"Filling must not be placed in such a manner that natural drainage from adjoining land will be\nobstructed or in such a manner that surface water will be diverted.\nFurther, any alterations to the natural surface contours must not impede or divert natural surface\nwater runoff so as to cause a nuisance to adjoining property owners.","stage":"during_work","stage_basis":"heading","page":19},{"label":"52","code":null,"number":"52","title":"Occupation Certificate Required","text":"An Occupation Certificate must be obtained prior to any use or occupation of the development.\nThe Principal Certifying Authority must be satisfied that the development has been constructed in\naccordance with approved plans, specifications and conditions of this consent.","stage":"before_oc","stage_basis":"heading","page":19},{"label":"53","code":null,"number":"53","title":"Repair of infrastructure","text":"","stage":"before_oc","stage_basis":"heading","page":19},{"label":"54","code":null,"number":"54","title":"Completion of landscape and tree works","text":"Before the issue of an occupation certificate, the principal certifier must be satisfied that all\nlandscape and tree-works, including pruning in accordance with AS 4373-2007 Pruning of amenity\ntrees and the removal of all noxious weed species, have been completed in accordance with the\napproved plans and any relevant conditions of this consent.","stage":"before_oc","stage_basis":"heading","page":20},{"label":"55","code":null,"number":"55","title":"Completion of Roads Act Approval works","text":"Before the issue of an occupation certificate, all approved road, footpath and/or drainage works,\nincluding vehicle crossings, have been completed in the road reserve in accordance with the Roads\nAct Approval to the satisfaction of the Council as the Roads Authority.","stage":"before_oc","stage_basis":"heading","page":20},{"label":"56","code":null,"number":"56","title":"Removal of waste upon completion","text":"Before the issue of an occupation certificate, the principal certifier must ensure all refuse, spoil and\nmaterial unsuitable for use on-site is removed from the site and disposed of in accordance with the\napproved waste management plan. Written evidence of the removal must be supplied to the\nsatisfaction of the principal certifier.\nBefore the issue of a partial occupation certificate, the applicant must ensure the temporary storage\nof any waste is carried out in accordance with the approved waste management plan to the principal\ncertifier’s satisfaction.","stage":"before_oc","stage_basis":"heading","page":20},{"label":"57","code":null,"number":"57","title":"Stormwater/drainage works","text":"All stormwater and drainage works required to be undertaken in accordance with this consent must\nbe completed before the issue of an occupation certificate.\nThe certification/verification must be provided to the satisfaction of the Principal Certifying\nAuthority.","stage":"before_oc","stage_basis":"heading","page":20},{"label":"58","code":null,"number":"58","title":"Car parking requirements","text":"Before the issue of an occupation certificate, car parking spaces are to be provided in accordance\nwith AS2890 and the approved plans.\nParking must be permanently marked on the pavement surface.","stage":"before_oc","stage_basis":"heading","page":20},{"label":"59","code":null,"number":"59","title":"Loading/Unloading Facilities","text":"Before the issue of an occupation certificate, loading / unloading facilities must be constructed in\naccordance with the approved plans. The extent of the loading bay must be permanently marked on\nthe pavement surface.","stage":"before_oc","stage_basis":"heading","page":21},{"label":"60","code":null,"number":"60","title":"Services","text":"Evidence is to be provided to Council demonstrating that the following reticulated services are\navailable to each lot:\na) Electricity;\nb) Water;\nc) Sewer; and\nd) Gas (where available).\nShould any of the above reticulated services not be available to the development site, a detailed\nstatement is to be provided explaining why connection of the relevant service is not possible or\npractical.","stage":"before_oc","stage_basis":"heading","page":21},{"label":"61","code":null,"number":"61","title":"Water authority certification","text":"Before the issue of an occupation certificate, a certificate of compliance must be obtained in relation\nto the proposed use from Hunter Water Corporation.","stage":"before_oc","stage_basis":"heading","page":21},{"label":"62","code":null,"number":"62","title":"Construction to be in accordance with Acoustic Report","text":"Certification is to be submitted to the Principal Certifying Authority to certify that the construction of\nthe development complies with the recommendations of the Acoustic Assessment Report No.\n20241271.1, Revision 2, prepared by Acoustic Logic and dated 17 December 2024.","stage":"before_oc","stage_basis":"heading","page":21},{"label":"63","code":null,"number":"63","title":"Bushfire safety","text":"The site is located within a bushfire prone area and must comply with NSW Rural Fire Service\ndocument \"Planning for Bushfire Protection 2019\" (PBP2019). In this regard the following is required:\n• The site must be managed as an ‘Inner Protection Area’ as outlined within PBP2019.\n• The development is to be constructed in accordance with the access provisions of Chapter 8\nof PBP 2019;\n• The development is to be connected to a reliable water supply network and suitable fire\nhydrants are to be clearly marked and provided for the purposes of bushfire protection. Fire\nhydrant spacing, fixing and pressure shall comply with AS2419.1 - 2005 and PBP 2019 (Table\n7.4a);\n• The provision of electricity must comply with Table 7.4a of PBP 2019;\n• Any hazardous materials must be stored away from the bushfire hazard wherever possible.\n• An Emergency Evacuation Plan is to be prepared.\nBefore the issue of an occupation certificate, details demonstrating compliance must be provided to\nthe Certifying Authority by an NSW suitably qualified BPAD Bushfire Consultant.","stage":"before_oc","stage_basis":"heading","page":21},{"label":"64","code":null,"number":"64","title":"Outdoor Lighting","text":"Prior to the issue of an occupation certificate, details demonstrating that all lighting complies with AS\n1158 ‘Lighting for Roads and Public Spaces’ and AS 4282 ‘Control of Obtrusive Effects of Outdoor\nLighting’ and the lighting controls detailed in the Civil Aviation Safety Authority (CASA) Manual of\nStandards (MOS-139) Aerodromes must be provided to the Certifying Authority.","stage":"before_oc","stage_basis":"heading","page":22},{"label":"65","code":null,"number":"65","title":"Driveways to be maintained","text":"All access crossings and driveways must be maintained in good order for the life of the development","stage":"ongoing","stage_basis":"heading","page":22},{"label":"66","code":null,"number":"66","title":"Impact to adjoining properties","text":"The development must not undertake activities which may restrict, obstruct or inconvenience the\nuse of the land by other users, outside of the approved development location.","stage":"ongoing","stage_basis":"heading","page":22},{"label":"67","code":null,"number":"67","title":"Industrial Uses","text":"All industrial activity in connection with the use of the subject property is to be wholly confined\nwithin the building.\nAny approved office space is to be used solely in conjunction with the industrial use of the premises\nto which it is attached. The separate use or occupation of the approved office space is not permitted\nby this consent.\nThe use of the factory unit for retail activities is prohibited.","stage":"ongoing","stage_basis":"heading","page":22},{"label":"68","code":null,"number":"68","title":"Loading to occur on site","text":"All loading and unloading operations are to be carried out wholly within the building/site and in\naccordance with the approved plans.\nThe loading dock (if provided) must be used for loading and unloading operations in connection with\nthe approved use.","stage":"ongoing","stage_basis":"heading","page":22},{"label":"69","code":null,"number":"69","title":"Maintenance of Landscaping","text":"Landscaping must be maintained in accordance with the approved landscape plan and conditions of\nthis development consent. All landscape areas must be kept free of parked vehicles, stored goods,\ngarbage or waste material at all times.\nIf any of the vegetation dies or is removed, it is to be replaced with vegetation of the same species\nand similar maturity as the vegetation which has died or was removed.","stage":"ongoing","stage_basis":"heading","page":23},{"label":"70","code":null,"number":"70","title":"Manoeuvring of Vehicles","text":"All vehicles must enter and exit the site in a forward direction.","stage":"ongoing","stage_basis":"heading","page":23},{"label":"71","code":null,"number":"71","title":"Offensive Noise","text":"The use and occupation of the premises including all plant and equipment must not give rise to any\noffensive noise within the meaning of the Protection of the Environment Operation Act 1997 and\nmust comply with the NSW Noise Policy for Industry 2017 (as amended).","stage":"ongoing","stage_basis":"heading","page":23},{"label":"72","code":null,"number":"72","title":"Parking areas to be kept clear","text":"At all times, the loading, car parking spaces, driveways and footpaths must be kept clear of goods\nand must not be used for storage purposes.","stage":"ongoing","stage_basis":"heading","page":23},{"label":"73","code":null,"number":"73","title":"Storage of goods","text":"The storage of goods and materials must be confined within the building. At no time must goods,\nmaterials or advertising signs be displayed or placed within the designated car parking spaces,\nlandscaped areas or road reserve.","stage":"ongoing","stage_basis":"heading","page":23},{"label":"74","code":null,"number":"74","title":"Amenity","text":"The business must be conducted, and customers controlled at all times so that no interference\noccurs to the amenity of the area, the footpath, adjoining occupations and residential or business\npremises.","stage":"ongoing","stage_basis":"heading","page":23},{"label":"75","code":null,"number":"75","title":"Maintenance of stormwater","text":"The stormwater system, including any water quality or quantity components, shall be maintained in\nperpetuity for the life of the development, in accordance with manufacturer’s instructions to ensure\nthat operational performance will be sustained in accordance with the design intent.","stage":"ongoing","stage_basis":"heading","page":24},{"label":"76","code":null,"number":"76","title":"Waste Management","text":"Operational waste management must be managed in accordance with the approved operational\nwaste management plan referenced in Condition 1.","stage":"ongoing","stage_basis":"heading","page":24},{"label":"77","code":null,"number":"77","title":"Waste Storage","text":"As the subject site is located in an area mapped by the Department of Defence as “Birdstrike Group\nC”, organic waste and/or the storage of bins associated with any future development must be\ncovered and/or enclosed and limited on-site.","stage":"ongoing","stage_basis":"heading","page":24},{"label":"78","code":null,"number":"78","title":"Hazardous material storage","text":"Dangerous and hazardous goods must be stored in accordance with SafeWork NSW requirements,\ndependent on the quantities stored. Any flammable or combustible liquids must be stored in\naccordance with AS 1940 'The Storage and Handling of Flammable and Combustible Liquids'.\nHazardous and/or industrial waste arising from the use must be removed and/or transported in\naccordance with the requirements of the Environmental Protection Agency and the SafeWork NSW.","stage":"ongoing","stage_basis":"heading","page":24},{"label":"79","code":null,"number":"79","title":"Hours of operation","text":"The property is only to be open for business and used for the purpose approved within the following\nhours:\nSecurity Guardhouse\nDay Hours of Operation\nMonday - Sunday 24hr\nOffice\nDay Hours of Operation\nMonday - Friday 7:00am - 3:30pm\nOther internal operations such as cleaning, preparation, and office administration may be\nundertaken outside of the above hours provided no disturbance to the amenity of the\nneighbourhood occurs.\nCondition reason - To ensure the development operates within the approved operating hours.","stage":"ongoing","stage_basis":"heading","page":24},{"label":"80","code":null,"number":"80","title":"Fire Safety Schedule","text":"At all times, a copy of the Fire Safety Schedule and Fire Safety Certificate must be prominently\ndisplayed in the building and a copy forwarded to the Commissioner of Fire and Rescue NSW in\naccordance with the Environmental Planning & Assessment Regulations 2021.","stage":"ongoing","stage_basis":"heading","page":25}]});
